function portalValidDate(string $value):bool{$date=DateTimeImmutable::createFromFormat('!Y-m-d',$value);return $date instanceof DateTimeImmutable&&$date->format('Y-m-d')===$value;}
function portalValidMonth(string $value):bool{return preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$value)===1;}
