    }
    $responses=$rq->fetchAll();
    $i=$pdo->prepare("SELECT i.id,i.invoice_no,i.issued_on,i.due_on,i.period_key,i.items,i.total,i.status,i.issuer_snapshot,(SELECT COALESCE(SUM(p.amount),0) FROM accounting_service_payments p WHERE p.owner_id=i.owner_id AND p.invoice_id=i.id) paid_amount,EXISTS(SELECT 1 FROM accounting_payment_notices n WHERE n.owner_id=i.owner_id AND n.invoice_id=i.id AND n.status='pending') payment_notice_pending,(SELECT n.review_comment FROM accounting_payment_notices n WHERE n.owner_id=i.owner_id AND n.invoice_id=i.id AND n.status='rejected' ORDER BY n.reviewed_at DESC LIMIT 1) payment_review_comment FROM accounting_service_invoices i WHERE i.owner_id=? AND i.client_id=? AND i.status<>'draft' ORDER BY i.issued_on DESC");
    $i->execute([$owner,$client]);
    $d=$pdo->prepare("SELECT d.id,d.period_key,d.doc_type,d.name,d.mime_type,d.status,d.created_at,d.version,d.previous_id,(SELECT JSON_UNQUOTE(JSON_EXTRACT(a.details,'$.comment')) FROM accounting_document_audit a WHERE a.owner_id=d.owner_id AND a.document_id=d.id AND a.action='reject' ORDER BY a.created_at DESC LIMIT 1) review_comment FROM accounting_documents d WHERE d.owner_id=? AND d.client_id=? AND d.archived=0 ORDER BY d.created_at DESC");
    $d->execute([$owner,$client]);
    $n=$pdo->prepare("SELECT id,title,message,created_at FROM notifications WHERE user_id=? AND type='accounting' AND entity_type='client' AND entity_id=? ORDER BY created_at DESC LIMIT 30");
    $n->execute([$uid,$client]);
    jsonResponse(true,'Кабінет клієнта завантажено.',['client'=>$entry,'clients'=>$allowed,'requests'=>$requests,'responses'=>$responses,'invoices'=>$i->fetchAll(),'documents'=>$d->fetchAll(),'messages'=>$n->fetchAll(),'manager_view'=>$managerPortal,'portal_only'=>accountingPortalOnlyUser($pdo,$uid,(string)$user['role'])]);
}
if($action==='respond'){
    $request=(string)($data['request_id']??'');
    $message=mb_substr(trim((string)($data['message']??'')),0,5000);
    $q=$pdo->prepare('SELECT id,period_key,title,status FROM accounting_client_requests WHERE id=? AND owner_id=? AND client_id=?');
    $q->execute([$request,$owner,$client]);
    $requestRow=$q->fetch();
    $file=$_FILES['file']??null;
    if(!$requestRow||(!$message&&(!$file||$file['error']===UPLOAD_ERR_NO_FILE)))jsonResponse(false,'Запит, відповідь або вкладення некоректні.',[],422);
    if($requestRow['status']==='received')jsonResponse(false,'Цей запит уже прийнято.',[],409);
    if($requestRow['status']==='rejected'&&(!$file||$file['error']===UPLOAD_ERR_NO_FILE))jsonResponse(false,'Додайте виправлений документ.',[],422);
    $docId=null;$docName=null;$storedPath=null;
    if($file&&$file['error']!==UPLOAD_ERR_NO_FILE){
        if($file['error']===UPLOAD_ERR_INI_SIZE||$file['error']===UPLOAD_ERR_FORM_SIZE)jsonResponse(false,'Максимальний розмір файла — 15 МБ.',[],422);
        if($file['error']!==UPLOAD_ERR_OK)jsonResponse(false,'Не вдалося завантажити файл. Спробуйте ще раз.',[],422);
        if($file['size']>15*1024*1024)jsonResponse(false,'Максимальний розмір файла — 15 МБ.',[],422);
        $ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));
        if(!preg_match('/^[a-z0-9]{1,10}$/',$ext))$ext='file';
        $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name'])?:'application/octet-stream';
        $dir=__DIR__.'/accounting-private';if(!is_dir($dir)&&!mkdir($dir,0700,true))jsonResponse(false,'Не вдалося створити приватне сховище.',[],500);
        $stored=bin2hex(random_bytes(18)).'.'.$ext;$storedPath=$dir.'/'.$stored;
        if(!move_uploaded_file($file['tmp_name'],$storedPath))jsonResponse(false,'Не вдалося зберегти файл.',[],500);
        $docId=bin2hex(random_bytes(16));$docName=mb_substr(basename((string)$file['name']),0,190);
        try{
            $previous=$pdo->prepare('SELECT d.id,d.version FROM accounting_client_responses r JOIN accounting_documents d ON d.id=r.document_id WHERE r.request_id=? AND d.owner_id=? AND d.client_id=? ORDER BY d.created_at DESC LIMIT 1');
            $previous->execute([$request,$owner,$client]);$lastVersion=$previous->fetch();
            $pdo->prepare('INSERT INTO accounting_documents(id,owner_id,client_id,period_key,doc_type,name,stored_name,mime_type,size_bytes,status,uploaded_by,version,previous_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$docId,$owner,$client,$requestRow['period_key'],'Вкладення до запиту: '.mb_substr((string)$requestRow['title'],0,55),$docName,$stored,$mime,(int)$file['size'],'pending_review',$uid,$lastVersion?(int)$lastVersion['version']+1:1,$lastVersion['id']??null]);
            $pdo->prepare('INSERT INTO accounting_document_audit(id,owner_id,document_id,user_id,action,details) VALUES(?,?,?,?,?,?)')->execute([bin2hex(random_bytes(16)),$owner,$docId,$uid,'response_upload',json_encode(['request_id'=>$request,'request_title'=>$requestRow['title']],JSON_UNESCAPED_UNICODE)]);
        }catch(Throwable $e){if(is_file($storedPath))unlink($storedPath);throw $e;}
    }
    $pdo->prepare('INSERT INTO accounting_client_responses(id,request_id,user_id,message,document_id) VALUES(?,?,?,?,?)')->execute([bin2hex(random_bytes(16)),$request,$uid,$message,$docId]);if($docId)$pdo->prepare("UPDATE accounting_client_requests SET status='pending_review' WHERE id=? AND owner_id=?")->execute([$request,$owner]);
    portalNotify($pdo,$owner,$uid,'Відповідь клієнта','Клієнт відповів на запит документів'.($docName?' і прикріпив файл: '.$docName:''),$client);
    if($docId){portalNotify($pdo,$owner,$uid,'Новий документ клієнта','Клієнт завантажив вкладення до запиту за період '.$requestRow['period_key'],$client);}
    jsonResponse(true,'Відповідь надіслано бухгалтеру.',['document_id'=>$docId,'document_name'=>$docName]);
}
if($action==='payment_notice'){
    $invoice=(string)($data['invoice_id']??'');
    $amount=filter_var($data['amount']??null,FILTER_VALIDATE_FLOAT);
    if($amount===false||$amount<=0)jsonResponse(false,'Перевірте рахунок і суму.',[],422);
    $file=$_FILES['proof']??null;$storedPath=null;$proofId=null;
    if($file&&$file['error']!==UPLOAD_ERR_NO_FILE){
        if(in_array($file['error'],[UPLOAD_ERR_INI_SIZE,UPLOAD_ERR_FORM_SIZE],true)||$file['size']>15*1024*1024)jsonResponse(false,'Максимальний розмір файла — 15 МБ.',[],422);
        if($file['error']!==UPLOAD_ERR_OK)jsonResponse(false,'Не вдалося завантажити підтвердження.',[],422);
        $ext=strtolower(pathinfo((string)$file['name'],PATHINFO_EXTENSION));
        $allowed=['pdf'=>'application/pdf','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png'];
        $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name'])?:'';
        if(!isset($allowed[$ext])||$allowed[$ext]!==$mime)jsonResponse(false,'Підтвердження має бути PDF, JPG або PNG.',[],422);
    }
    $pdo->beginTransaction();
    try{
        $q=$pdo->prepare('SELECT id,status,period_key,total FROM accounting_service_invoices WHERE id=? AND owner_id=? AND client_id=? FOR UPDATE');
        $q->execute([$invoice,$owner,$client]);$invoiceRow=$q->fetch();
        if(!$invoiceRow){$pdo->rollBack();jsonResponse(false,'Рахунок не знайдено.',[],404);}
        if(in_array((string)$invoiceRow['status'],['draft','cancelled','paid'],true)){$pdo->rollBack();jsonResponse(false,'Для цього рахунка не можна надіслати повідомлення про оплату.',[],409);}
        $paidQuery=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM accounting_service_payments WHERE owner_id=? AND invoice_id=?');$paidQuery->execute([$owner,$invoice]);
        $remaining=round((float)$invoiceRow['total']-(float)$paidQuery->fetchColumn(),2);
        if($amount>$remaining+0.001){$pdo->rollBack();jsonResponse(false,'Сума повідомлення перевищує залишок за рахунком.',[],422);}
        $pending=$pdo->prepare("SELECT 1 FROM accounting_payment_notices WHERE owner_id=? AND invoice_id=? AND status='pending' LIMIT 1");
        $pending->execute([$owner,$invoice]);if($pending->fetchColumn()){$pdo->rollBack();jsonResponse(false,'Повідомлення про оплату цього рахунка вже очікує перевірки.',[],409);}
        if($file&&$file['error']===UPLOAD_ERR_OK){
            $dir=__DIR__.'/accounting-private';if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new RuntimeException('Private storage unavailable');
            $stored=bin2hex(random_bytes(18)).'.'.$ext;$storedPath=$dir.'/'.$stored;
            if(!move_uploaded_file($file['tmp_name'],$storedPath))throw new RuntimeException('Upload failed');
            $proofId=bin2hex(random_bytes(16));
            $pdo->prepare('INSERT INTO accounting_documents(id,owner_id,client_id,period_key,doc_type,name,stored_name,mime_type,size_bytes,status,uploaded_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$proofId,$owner,$client,$invoiceRow['period_key'],'Підтвердження оплати',mb_substr(basename((string)$file['name']),0,190),$stored,$mime,(int)$file['size'],'pending_review',$uid]);
        }
        $pdo->prepare('INSERT INTO accounting_payment_notices(id,owner_id,client_id,invoice_id,user_id,amount,comment,proof_document_id) VALUES(?,?,?,?,?,?,?,?)')->execute([bin2hex(random_bytes(16)),$owner,$client,$invoice,$uid,$amount,mb_substr((string)($data['comment']??''),0,1000),$proofId]);
        $pdo->commit();
    }catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();if($storedPath&&is_file($storedPath))unlink($storedPath);throw $error;}
    portalNotify($pdo,$owner,$uid,'Оплата від клієнта','Клієнт повідомив про оплату рахунка.',$client);
    jsonResponse(true,'Повідомлення про оплату передано бухгалтеру на перевірку.');
}
jsonResponse(false,'Невідома дія.',[],422);
